mapper.select:
SELECT
FROM ESS_LEAVE_APPLY_TB EL, HR_EMPLOYEE HR WHERE EL.PERSON_ID = HR.PERSON_ID(+) AND EL.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND EL.ACTIVITY = '1' AND EL.BATCH_YN <> '2' AND (EL.PERSON_ID NOT LIKE '111111%' OR (EL.PERSON_ID IS NULL AND EL.CREATED_BY = #{adminID, jdbcType=VARCHAR}))
AND (EXISTS (SELECT B1.DEPTID FROM HR_DEPARTMENT B1 WHERE B1.DEPTNO = HR.DEPTNO START WITH B1.DEPTNO IN (SELECT HRD.DEPTID FROM HR_DEPARTMENT HRD WHERE HRD.MANAGER_EMP_ID = #{adminID, jdbcType=VARCHAR}) CONNECT BY PRIOR B1.DEPTNO = B1.PARENT_DEPT_NO UNION SELECT AR_SUPERVISOR_INFO.DEPTNO FROM AR_SUPERVISOR_INFO WHERE AR_SUPERVISOR_INFO.DEPTNO = HR.DEPTNO AND AR_SUPERVISOR_INFO.PERSON_ID = #{adminID, jdbcType=VARCHAR}) OR EL.PERSON_ID IS NULL)
AND INSTR(',' || #{deptNos, jdbcType=VARCHAR} || ',', ',' || HR.DEPTNO || ',') > 0
AND TO_CHAR(HR.POST_FAMILY) = #{searchPostFamily, jdbcType=VARCHAR}
AND GET_AR_SHIFTNO(EL.PERSON_ID, TO_CHAR(EL.APPLY_TIME, 'YYYY/MM/DD'), EL.CPNY_ID) = #{shiftNo, jdbcType=VARCHAR}
AND (HR.EMPID LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR CONVERTTOUNSIGN(UPPER(HR.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%' OR UPPER(HR.ENGLISH_NAME) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%')
AND TO_CHAR(EL.LEAVE_TYPE_CODE) = #{searchLeaveTypeCode, jdbcType=VARCHAR}
AND TO_CHAR(EL.AFFIRM_FLAG) = #{searchAffirmFlag, jdbcType=VARCHAR}
AND NVL(TO_CHAR(EL.AFFIRM_FLAG), ' ') <> '14014310'
AND TO_CHAR(EL.CONFIRM_FLAG) = #{searchConfirmFlag, jdbcType=VARCHAR}
AND ((TRUNC(EL.LEAVE_FROM_TIME) >= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'DD/MM/YYYY') AND TRUNC(EL.LEAVE_FROM_TIME) <= TO_DATE(#{endDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')) OR (TRUNC(EL.LEAVE_FROM_TIME) <= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'DD/MM/YYYY') AND TRUNC(EL.LEAVE_TO_TIME) > TO_DATE(#{endDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')) OR (TRUNC(EL.LEAVE_TO_TIME) > TO_DATE(#{startDate, jdbcType=VARCHAR}, 'DD/MM/YYYY') AND TRUNC(EL.LEAVE_TO_TIME) < TO_DATE(#{endDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')))
ORDER BY EL.APPLY_TIME DESC NULLS FIRST, EL.APPLY_NO DESC

mapper.delete:
DELETE FROM ESS_LEAVE_APPLY_TB
 WHERE PERSON_ID IS NULL
   AND CREATED_BY = #{adminID, jdbcType=VARCHAR}
